7	/**
8	 * Interface for the ModelConfigService to break circular dependencies.
9	 */
10	export interface IModelConfigService {
11	  getModelDefinition(modelId: string):
12	    | {
13	        tier?: string;
14	        family?: string;
15	        isPreview?: boolean;
16	        displayName?: string;
17	        features?: {
18	          thinking?: boolean;
19	          multimodalToolUse?: boolean;
20	        };
21	      }
22	    | undefined;
23	}
24	
25	/**
26	 * Interface defining the minimal configuration required for model capability checks.
27	 * This helps break circular dependencies between Config and models.ts.
28	 */
29	export interface ModelCapabilityContext {
30	  readonly modelConfigService: IModelConfigService;
31	  getExperimentalDynamicModelConfiguration(): boolean;
32	}
33	
34	export const PREVIEW_GEMINI_MODEL = 'gemini-3-pro-preview';
35	export const PREVIEW_GEMINI_3_1_MODEL = 'gemini-3.1-pro-preview';
36	export const PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL =
37	  'gemini-3.1-pro-preview-customtools';
38	export const PREVIEW_GEMINI_FLASH_MODEL = 'gemini-3-flash-preview';
39	export const DEFAULT_GEMINI_MODEL = 'gemini-2.5-pro';
40	export const DEFAULT_GEMINI_FLASH_MODEL = 'gemini-2.5-flash';
41	export const DEFAULT_GEMINI_FLASH_LITE_MODEL = 'gemini-2.5-flash-lite';
42	
43	export const VALID_GEMINI_MODELS = new Set([
44	  PREVIEW_GEMINI_MODEL,
45	  PREVIEW_GEMINI_3_1_MODEL,
46	  PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL,
47	  PREVIEW_GEMINI_FLASH_MODEL,
48	  DEFAULT_GEMINI_MODEL,
49	  DEFAULT_GEMINI_FLASH_MODEL,
50	  DEFAULT_GEMINI_FLASH_LITE_MODEL,
51	]);
52	
53	export const PREVIEW_GEMINI_MODEL_AUTO = 'auto-gemini-3';
54	export const DEFAULT_GEMINI_MODEL_AUTO = 'auto-gemini-2.5';
55	
56	// Model aliases for user convenience.
57	export const GEMINI_MODEL_ALIAS_AUTO = 'auto';
58	export const GEMINI_MODEL_ALIAS_PRO = 'pro';
59	export const GEMINI_MODEL_ALIAS_FLASH = 'flash';
60	export const GEMINI_MODEL_ALIAS_FLASH_LITE = 'flash-lite';
61	
62	export const DEFAULT_GEMINI_EMBEDDING_MODEL = 'gemini-embedding-001';
63	
64	// Cap the thinking at 8192 to prevent run-away thinking loops.
65	export const DEFAULT_THINKING_MODE = 8192;
66	
67	/**
68	 * Resolves the requested model alias (e.g., 'auto-gemini-3', 'pro', 'flash', 'flash-lite')
69	 * to a concrete model name.
70	 *
71	 * @param requestedModel The model alias or concrete model name requested by the user.
72	 * @param useGemini3_1 Whether to use Gemini 3.1 Pro Preview for auto/pro aliases.
73	 * @param hasAccessToPreview Whether the user has access to preview models.
74	 * @returns The resolved concrete model name.
75	 */
76	export function resolveModel(
77	  requestedModel: string,
78	  useGemini3_1: boolean = false,
79	  useCustomToolModel: boolean = false,
80	  hasAccessToPreview: boolean = true,
81	): string {
82	  let resolved: string;
83	  switch (requestedModel) {
84	    case PREVIEW_GEMINI_MODEL:
85	    case PREVIEW_GEMINI_MODEL_AUTO:
86	    case GEMINI_MODEL_ALIAS_AUTO:
87	    case GEMINI_MODEL_ALIAS_PRO: {
88	      if (useGemini3_1) {
89	        resolved = useCustomToolModel
90	          ? PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL
91	          : PREVIEW_GEMINI_3_1_MODEL;
92	      } else {
93	        resolved = PREVIEW_GEMINI_MODEL;
94	      }
95	      break;
96	    }
97	    case DEFAULT_GEMINI_MODEL_AUTO: {
98	      resolved = DEFAULT_GEMINI_MODEL;
99	      break;
100	    }
101	    case GEMINI_MODEL_ALIAS_FLASH: {
102	      resolved = PREVIEW_GEMINI_FLASH_MODEL;
103	      break;
104	    }
105	    case GEMINI_MODEL_ALIAS_FLASH_LITE: {
106	      resolved = DEFAULT_GEMINI_FLASH_LITE_MODEL;
107	      break;
108	    }
109	    default: {
110	      resolved = requestedModel;
111	      break;
112	    }
113	  }
114	
115	  if (!hasAccessToPreview && isPreviewModel(resolved)) {
116	    // Downgrade to stable models if user lacks preview access.
117	    switch (resolved) {
118	      case PREVIEW_GEMINI_FLASH_MODEL:
119	        return DEFAULT_GEMINI_FLASH_MODEL;
120	      case PREVIEW_GEMINI_MODEL:
121	      case PREVIEW_GEMINI_3_1_MODEL:
122	      case PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL:
123	        return DEFAULT_GEMINI_MODEL;
124	      default:
125	        // Fallback for unknown preview models, preserving original logic.
126	        if (resolved.includes('flash-lite')) {
127	          return DEFAULT_GEMINI_FLASH_LITE_MODEL;
128	        }
129	        if (resolved.includes('flash')) {
130	          return DEFAULT_GEMINI_FLASH_MODEL;
131	        }
132	        return DEFAULT_GEMINI_MODEL;
133	    }
134	  }
135	
136	  return resolved;
137	}
