139	/**
140	 * Resolves the appropriate model based on the classifier's decision.
141	 *
142	 * @param requestedModel The current requested model (e.g. auto-gemini-2.5).
143	 * @param modelAlias The alias selected by the classifier ('flash' or 'pro').
144	 * @returns The resolved concrete model name.
145	 */
146	export function resolveClassifierModel(
147	  requestedModel: string,
148	  modelAlias: string,
149	  useGemini3_1: boolean = false,
150	  useCustomToolModel: boolean = false,
151	): string {
152	  if (modelAlias === GEMINI_MODEL_ALIAS_FLASH) {
153	    if (
154	      requestedModel === DEFAULT_GEMINI_MODEL_AUTO ||
155	      requestedModel === DEFAULT_GEMINI_MODEL
156	    ) {
157	      return DEFAULT_GEMINI_FLASH_MODEL;
158	    }
159	    if (
160	      requestedModel === PREVIEW_GEMINI_MODEL_AUTO ||
161	      requestedModel === PREVIEW_GEMINI_MODEL
162	    ) {
163	      return PREVIEW_GEMINI_FLASH_MODEL;
164	    }
165	    return resolveModel(GEMINI_MODEL_ALIAS_FLASH);
166	  }
167	  return resolveModel(requestedModel, useGemini3_1, useCustomToolModel);
168	}
169	export function getDisplayString(
170	  model: string,
171	  config?: ModelCapabilityContext,
172	) {
173	  if (config?.getExperimentalDynamicModelConfiguration?.() === true) {
174	    const definition = config.modelConfigService.getModelDefinition(model);
175	    if (definition?.displayName) {
176	      return definition.displayName;
177	    }
178	  }
179	
180	  switch (model) {
181	    case PREVIEW_GEMINI_MODEL_AUTO:
182	      return 'Auto (Gemini 3)';
183	    case DEFAULT_GEMINI_MODEL_AUTO:
184	      return 'Auto (Gemini 2.5)';
185	    case GEMINI_MODEL_ALIAS_PRO:
186	      return PREVIEW_GEMINI_MODEL;
187	    case GEMINI_MODEL_ALIAS_FLASH:
188	      return PREVIEW_GEMINI_FLASH_MODEL;
189	    case PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL:
190	      return PREVIEW_GEMINI_3_1_MODEL;
191	    default:
192	      return model;
193	  }
194	}
