196	/**
197	 * Checks if the model is a preview model.
198	 *
199	 * @param model The model name to check.
200	 * @param config Optional config object for dynamic model configuration.
201	 * @returns True if the model is a preview model.
202	 */
203	export function isPreviewModel(
204	  model: string,
205	  config?: ModelCapabilityContext,
206	): boolean {
207	  if (config?.getExperimentalDynamicModelConfiguration?.() === true) {
208	    return (
209	      config.modelConfigService.getModelDefinition(model)?.isPreview === true
210	    );
211	  }
212	
213	  return (
214	    model === PREVIEW_GEMINI_MODEL ||
215	    model === PREVIEW_GEMINI_3_1_MODEL ||
216	    model === PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL ||
217	    model === PREVIEW_GEMINI_FLASH_MODEL ||
218	    model === PREVIEW_GEMINI_MODEL_AUTO ||
219	    model === GEMINI_MODEL_ALIAS_AUTO
220	  );
221	}
